              f"I={sample.get('current_a')} A  T={sample.get('temp_c')} C  "
              f"state={sample.get('state')}", flush=True)
        self._send(200, b'{"ok":true}', "application/json")

    def log_message(self, fmt, *args):  # 静音默认访问日志
        return


